using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using AntColony.Units;
public static class Native1112ActionAudit{public static async Task<string> Run(){var p=UnityEngine.Object.FindAnyObjectByType<MeshyNativeMotionPlayer>();var v=p.GetComponent<AntVisual>();p.PreviewMotion=null;p.PreviewPhase=-1;var lib=Resources.Load<MeshyNativeLibrary>("MeshyNative/Runtime");var report=new System.Collections.Generic.List<string>();AntColony.UI.SimulationPause.UserSpeed(1);EditorApplication.isPaused=false;try{foreach(var a in lib.actions){v.Action(a.action,60);await Task.Delay(70);var resolved=lib.actions.FirstOrDefault(b=>b.action==v.MotionName);if(resolved==null||p.PlayingMotion!=resolved.motion)throw new Exception(a.action+" -> "+v.MotionName+" / "+p.PlayingMotion);report.Add(a.action+" -> "+v.MotionName+" -> "+p.PlayingMotion+" PASS");}File.WriteAllLines("work/animation-1112/action-routing.txt",report);return report.Count+" visual action API bindings PASS; natural gameplay is tested separately";}finally{AntColony.UI.SimulationPause.UserSpeed(0);v.Action("Idle_A");}}}
